import re

from moler.exceptions import ParsingDone, CommandFailure

from ta_moler.cmd.rtg.rtg.genericrtg import GenericRtg

__author__ = 'Dawid Gwizdz'
__copyright__ = 'Copyright (C) 2020, Nokia'
__email__ = 'dawid.gwizdz@gmail.com'


class ConfigRemoteReload(GenericRtg):
    """Configremotereload command class."""

    def __init__(self, connection, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Configremotereload command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(ConfigRemoteReload, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "config remote reload"
        if self.options:
            cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_rerun(line)
                self._parse_invalid_target(line)
                self._parse_successful(line)
            except ParsingDone:
                pass
        return super(ConfigRemoteReload, self).on_new_line(line, is_full_line)

    # Example line:     `::::::::::88::88::88:::88::::::::::'     !! RERUN THIS COMMAND TO START !!
    _re_rerun = re.compile(r"^\s*`::::::::::88::88::88:::88::::::::::'\s*!! RERUN THIS COMMAND TO START !!$")

    def _parse_rerun(self, line):
        """
        Parse rerun case in line.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_rerun, line):
            self.connection.sendline(self.command_string)
            raise ParsingDone

    # Example: Invalid target specs: invalid_target
    _re_invalid_target = re.compile(r"(?P<ERROR>Invalid target specs:\s*)")

    def _parse_invalid_target(self, line):
        """
        Parse invalid target error case in line.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_invalid_target, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))
            raise ParsingDone

    # Example line: 10:17:45|c1|CTRL-1 RETURN CODE: 0
    _re_successful = re.compile(r"(?P<SUCCESS>RETURN CODE:\s+0)")

    def _parse_successful(self, line):
        """
        Parse line contains successfully status.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_successful, line):
            self.set_result({})
            raise ParsingDone


